<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    image</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">ghcr.io/ni-c/mcp-hub-docker-proxy:0.7.0</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # pin a digest in production</span></span>
